define struct Rectangle {
    Point top_left;
    Point bottom_right;
} with {
    constructor(Point a, Point b) { self.top_left = a; self.bottom_right = b; }
    mtd area() -> int { return (self.bottom_right.x - self.top_left.x) * (self.bottom_right.y - self.top_left.y); }
